import java.io.*;
import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import javax.servlet.annotation.*;
import org.apache.commons.text.StringSubstitutor;
import java.util.*;

@WebServlet("/report")
public class ReportServlet extends HttpServlet {

    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {

        String reportType = req.getParameter("type");
        String startDate = req.getParameter("start");
        String endDate = req.getParameter("end");
        String customFilter = req.getParameter("filter");

        if (reportType == null || startDate == null || endDate == null) {
            resp.sendError(400, "Missing required parameters");
            return;
        }

        // Template-based query construction for different report types
        Map<String, String> templates = new HashMap<>();
        templates.put("sales", "SELECT product_name, SUM(amount) as total FROM sales WHERE sale_date BETWEEN '${start}' AND '${end}' ${filter} GROUP BY product_name");
        templates.put("inventory", "SELECT item_name, quantity FROM inventory WHERE last_updated BETWEEN '${start}' AND '${end}' ${filter} ORDER BY quantity DESC");
        templates.put("users", "SELECT username, email, last_login FROM users WHERE created_at BETWEEN '${start}' AND '${end}' ${filter}");

        String queryTemplate = templates.get(reportType);
        if (queryTemplate == null) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // Build substitution values
        Map<String, String> values = new HashMap<>();
        values.put("start", startDate);
        values.put("end", endDate);
        values.put("filter", customFilter != null ? "AND " + customFilter : "");

        // Perform template substitution
        StringSubstitutor sub = new StringSubstitutor(values);
        String finalQuery = sub.replace(queryTemplate);

        // Execute and return results
        resp.setContentType("application/json");
        PrintWriter out = resp.getWriter();

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(finalQuery)) {

            ResultSetMetaData meta = rs.getMetaData();
            int cols = meta.getColumnCount();
            StringBuilder json = new StringBuilder("[\n");
            boolean first = true;

            while (rs.next()) {
                if (!first) json.append(",\n");
                json.append("  {");
                for (int i = 1; i <= cols; i++) {
                    if (i > 1) json.append(", ");
                    json.append("\"").append(meta.getColumnLabel(i)).append("\": ");
                    json.append("\"").append(rs.getString(i)).append("\"");
                }
                json.append("}");
                first = false;
            }
            json.append("\n]");
            out.print(json.toString());

        } catch (SQLException e) {
            resp.sendError(500, "Query execution failed: " + e.getMessage());
        }
    }
}
